<?phpclass M_pay extends CI_Model {    public $_table_name = 'pay';    public function __construst() {        parent::__construst();    }    private function generate_where($args) {        if (isset($args['q'])) {            $this->db->group_start();            $this->db->like("ctm.full_name", $args['q']);            $this->db->or_like($this->_table_name . ".id", $args['q']);            $this->db->group_end();        }        if (isset($args['in_id'])) {            $this->db->where_in($this->_table_name . ".id", $args['in_id']);        }        if (isset($args['customer_id'])) {            $this->db->where($this->_table_name . ".customer_id", $args['customer_id']);        }    }    private function generate_order_by($args) {        $allow_sort = array("DESC", "ASC");        if (isset($args['order_by']) && is_array($args['order_by']) && !empty($args['order_by'])) {            foreach ($args['order_by'] as $key => $value) {                $sort = in_array($value, $allow_sort) ? $value : "DESC";                $this->db->order_by($this->_table_name . '.' . $key, $sort);            }        }    }    public function gets($args, $perpage = 5, $offset = -1) {        $this->db->select($this->_table_name . '.*, ctm.full_name as full_name');        $this->db->from($this->_table_name);        $this->db->join('customers as ctm', $this->_table_name . '.customer_id = ctm.id', 'left');        $this->generate_where($args);        $this->generate_order_by($args);        if ($offset >= 0) {            $this->db->limit($perpage, $offset);        }        $query = $this->db->get();        return $query->result_array();    }    public function counts($args) {        $this->db->select($this->_table_name . '.*, ctm.full_name as full_name');        $this->db->from($this->_table_name);        $this->db->join('customers as ctm', $this->_table_name . '.customer_id = ctm.id', 'left');        $this->generate_where($args);        $query = $this->db->get();        return $query->num_rows();    }    public function get($id) {        $this->db->select($this->_table_name . '.*, ctm.full_name as full_name');        $this->db->from($this->_table_name);        $this->db->join('customers as ctm', $this->_table_name . '.customer_id = ctm.id', 'left');        $this->db->where($this->_table_name . '.id', $id);        $query = $this->db->get();        return $query->row_array();    }    public function get_paid($args) {        $this->db->select_sum('amount');        $this->db->from($this->_table_name);        $this->generate_where($args);        $query = $this->db->get();        $row = $query->row_array();        return isset($row['amount']) ? $row['amount'] : 0;    }    public function add($data = array()) {        if (empty($data)) {            return 0;        }        $query = $this->db->insert($this->_table_name, $data);        $insert_id = $this->db->insert_id();        return (isset($query)) ? $insert_id : 0;    }    public function update($id, $data) {        if (empty($data)) {            return FALSE;        }        $this->db->where('id', $id);        $query = $this->db->update($this->_table_name, $data);        return (isset($query)) ? true : false;    }    public function delete($id) {        $this->db->where('id', $id);        $query = $this->db->delete($this->_table_name);        return (isset($query)) ? true : false;    }}/* End of file m_pay.php *//* Location: ./application/modules/pay/models/m_pay.php */